"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[53971],{38609:t=>{t.exports=JSON.parse('{"id":"2026-08-13-viber-template-send-examples","date":"2026-08-13","products":["Connect","APIs"],"product":"Connect","channel":"Viber","changeType":"Added","title":"Viber template send examples in the Send message reference","excerpt":"The Send message API reference now includes worked request examples for sending Viber template messages, covering both template categories: transactional templates and OTP templates.","hasArticle":true,"bodyHtml":"<p>The <strong>Send message</strong> API reference now includes worked request examples for sending Viber template messages, covering both template categories: transactional templates and OTP templates.</p>\\n<h2>Transactional template example</h2>\\n<pre><code class=\\"language-json\\">{\\n  &quot;user&quot;: { &quot;msisdn&quot;: &quot;+6500000&quot; },\\n  &quot;type&quot;: &quot;template&quot;,\\n  &quot;content&quot;: {\\n    &quot;template&quot;: {\\n      &quot;name&quot;: &quot;&lt;Insert Template Name&gt;&quot;,\\n      &quot;language&quot;: &quot;en&quot;,\\n      &quot;components&quot;: [\\n        {\\n          &quot;type&quot;: &quot;body&quot;,\\n          &quot;parameters&quot;: [\\n            { &quot;type&quot;: &quot;text&quot;, &quot;name&quot;: &quot;name&quot;, &quot;text&quot;: &quot;Ana&quot; },\\n            { &quot;type&quot;: &quot;text&quot;, &quot;name&quot;: &quot;orderId&quot;, &quot;text&quot;: &quot;10293847&quot; },\\n            { &quot;type&quot;: &quot;text&quot;, &quot;name&quot;: &quot;date&quot;, &quot;text&quot;: &quot;15 Aug 2026&quot; }\\n          ]\\n        }\\n      ]\\n    }\\n  }\\n}\\n</code></pre>\\n<h2>OTP template example</h2>\\n<pre><code class=\\"language-json\\">{\\n  &quot;user&quot;: { &quot;msisdn&quot;: &quot;+6500000&quot; },\\n  &quot;type&quot;: &quot;template&quot;,\\n  &quot;content&quot;: {\\n    &quot;template&quot;: {\\n      &quot;name&quot;: &quot;&lt;Insert Template Name&gt;&quot;,\\n      &quot;language&quot;: &quot;en&quot;,\\n      &quot;components&quot;: [\\n        {\\n          &quot;type&quot;: &quot;body&quot;,\\n          &quot;parameters&quot;: [\\n            { &quot;type&quot;: &quot;text&quot;, &quot;name&quot;: &quot;pin&quot;, &quot;text&quot;: &quot;1234&quot; }\\n          ]\\n        }\\n      ]\\n    }\\n  }\\n}\\n</code></pre>\\n<p>Both examples are available directly in the request body examples dropdown on the Send message endpoint.</p>\\n<h2>Read more</h2>\\n<ul>\\n<li><a href=\\"/connect/reference/send-message\\">Send message \u2014 API reference</a></li>\\n<li><a href=\\"/connect/docs/viber-templates-management\\">Viber Templates Management</a></li>\\n</ul>\\n"}')}}]);